// Shared wire/request byte builders for the pay/receive e2e flows. Reads `dfx/wire_layout.json`
// (the single source of truth, generated by `dpay-fixture wire-layout`) so the offsets/lengths are
// NEVER hand-transcribed — same discipline as the wasm core and `tests/00-cross-val.mjs`.
//
// Used by flows 06 (decode a request QR), 07 (build a second wallet's request + scan-pay), 09
// (sign + replay a double-spend), 10 (build an expired request). The byte math mirrors the Rust
// core exactly; `tests/00-cross-val.mjs` proves the SAME math produces byte-identical sigs/wires to
// the Rust core, so authorizations built here settle on the real FakeLedger (which verifies sigs).
//
// Signing uses @noble/ed25519 (RFC 8032; binary-compatible with ed25519-dalek `verify_strict`).
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import * as ed from '@noble/ed25519';

const __dirname = dirname(fileURLToPath(import.meta.url));
const WIRE_LAYOUT = join(__dirname, '..', '..', 'dfx', 'wire_layout.json');
const L = JSON.parse(readFileSync(WIRE_LAYOUT, 'utf8'));

// --- low-level hex / int codec (operates only on the offsets/lengths from the JSON) ------------
// MC1 units 2-4: u64 read/write via BigInt so the FULL u64 range is exact (never `Math.floor`/
// `& 0xff`, which is lossy above 2^53). A small JSON-number golden (e.g. 2500) round-trips
// byte-identically to the old lossy path. read returns an UNSIGNED decimal STRING (never `number`).
function hexToBytes(h) { return Uint8Array.from(Buffer.from(h, 'hex')); }
function bytesToHex(b) { return Buffer.from(b).toString('hex'); }

function putU64Le(buf, offset, val) {
  let v = BigInt(val);
  for (let i = 0; i < 8; i++) { buf[offset + i] = Number(v & 0xffn); v >>= 8n; }
}
function readU64Le(buf, offset) {
  let v = 0n; for (let i = 7; i >= 0; i--) v = (v << 8n) | BigInt(buf[offset + i]); return v.toString();
}
function putU32Le(buf, offset, val) {
  let v = Math.floor(val);
  for (let i = 0; i < 4; i++) { buf[offset + i] = v & 0xff; v = Math.floor(v / 0x100); }
}
function readU32Le(buf, offset) {
  let v = 0; for (let i = 3; i >= 0; i--) v = v * 0x100 + buf[offset + i]; return v;
}

// base64url (RFC 4648 §5, no padding) — mirrors Rust's `URL_SAFE_NO_PAD` and the shim's codec.
const B64_URL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
const B64_URL_REV = (() => { const m = {}; for (let i = 0; i < B64_URL.length; i++) m[B64_URL[i]] = i; return m; })();
export function b64urlEncode(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = i + 1 < bytes.length ? bytes[i + 1] : 0, b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    out += B64_URL[b0 >> 2];
    out += B64_URL[((b0 & 0x03) << 4) | (b1 >> 4)];
    if (i + 1 < bytes.length) out += B64_URL[((b1 & 0x0f) << 2) | (b2 >> 6)];
    if (i + 2 < bytes.length) out += B64_URL[b2 & 0x3f];
  }
  return out;
}
export function b64urlDecode(s) {
  const cleaned = String(s).replace(/=+$/g, '');
  const bytes = [];
  for (let i = 0; i < cleaned.length; i += 4) {
    const c0 = B64_URL_REV[cleaned[i]], c1 = B64_URL_REV[cleaned[i + 1]];
    const c2 = i + 2 < cleaned.length ? B64_URL_REV[cleaned[i + 2]] : undefined;
    const c3 = i + 3 < cleaned.length ? B64_URL_REV[cleaned[i + 3]] : undefined;
    if (c0 === undefined || c1 === undefined) throw new Error('base64url: bad char');
    bytes.push((c0 << 2) | (c1 >> 4));
    if (c2 !== undefined) bytes.push(((c1 & 0x0f) << 4) | (c2 >> 2));
    if (c3 !== undefined) bytes.push(((c2 & 0x03) << 6) | c3);
  }
  return Uint8Array.from(bytes);
}

// --- display name + memo codec (NUL-padded UTF-8, truncate to 32 bytes) -----------------------
// Mirrors `dpay_core::pad_name` + the canister's `display_field_to_string`. Empty = all zeros.
const NAME_LEN = 32;
export function padName32(s) {
  const utf8 = Buffer.from(s, 'utf8');
  const buf = Buffer.alloc(NAME_LEN);
  utf8.subarray(0, NAME_LEN).copy(buf); // truncate; rest is zero-filled (NUL-pad)
  return Uint8Array.from(buf);
}
export function trimName32(bytes) {
  let end = bytes.indexOf(0);
  if (end < 0) end = bytes.length;
  try { return Buffer.from(bytes.subarray(0, end)).toString('utf8'); } catch { return ''; }
}

// --- the 132-byte request (merchant's QR):
//     to(32)|amount_le(8)|nonce(16)|expiry_le(8)|currency_le(4)|to_name(32)|memo(32)
export function buildRequestBytes(toHex, amount, nonceHex, expiry, currency, toName = '', memo = '') {
  const buf = new Uint8Array(L.request_len);
  buf.set(hexToBytes(toHex), L.request_fields.to.offset);
  putU64Le(buf, L.request_fields.amount.offset, amount);
  buf.set(hexToBytes(nonceHex), L.request_fields.nonce.offset);
  putU64Le(buf, L.request_fields.expiry.offset, expiry);
  putU32Le(buf, L.request_fields.currency.offset, currency);
  buf.set(padName32(toName), L.request_fields.to_name.offset);
  buf.set(padName32(memo), L.request_fields.memo.offset);
  return buf;
}
/** The full merchant QR string the app scans: plain base64url of the 132-byte request (the
 *  `to_name` lives inside the bytes now — the old `|name` suffix is gone). */
export function buildRequestQR(toHex, amount, nonceHex, expiry, currency, toName = '', memo = '') {
  return b64urlEncode(buildRequestBytes(toHex, amount, nonceHex, expiry, currency, toName, memo));
}

/** Decode a 132-byte request (from base64url) into its fields, including to_name + memo. Tolerates
 *  a stray `|name` suffix defensively, but no name is carried there anymore. */
export function decodeRequest(b64OrQR) {
  const b64 = b64OrQR.includes('|') ? b64OrQR.slice(0, b64OrQR.indexOf('|')) : b64OrQR;
  const bytes = b64urlDecode(b64);
  if (bytes.length !== L.request_len) throw new Error(`request length: expected ${L.request_len}, got ${bytes.length}`);
  const toHex = bytesToHex(bytes.slice(L.request_fields.to.offset, L.request_fields.to.offset + L.request_fields.to.len));
  const amount = readU64Le(bytes, L.request_fields.amount.offset);
  const nonceHex = bytesToHex(bytes.slice(L.request_fields.nonce.offset, L.request_fields.nonce.offset + L.request_fields.nonce.len));
  const expiry = readU64Le(bytes, L.request_fields.expiry.offset);
  const currency = readU32Le(bytes, L.request_fields.currency.offset);
  const toName = trimName32(bytes.slice(L.request_fields.to_name.offset, L.request_fields.to_name.offset + L.request_fields.to_name.len));
  const memo = trimName32(bytes.slice(L.request_fields.memo.offset, L.request_fields.memo.offset + L.request_fields.memo.len));
  return { toHex, amount, nonceHex, expiry, currency, toName, memo };
}

// --- the 196-byte signing buffer + 292-byte wire (mirrors dpay_core::Authorization::signing_bytes)
//   from(32)|to(32)|amount_le(8)|nonce(16)|expiry_le(8)|currency_le(4)|from_name(32)|to_name(32)|memo(32)
function buildSigningBytes(fromHex, toHex, amount, nonceHex, expiry, currency, fromName = '', toName = '', memo = '') {
  const buf = new Uint8Array(L.signing_len);
  buf.set(hexToBytes(fromHex), L.fields.from.offset);
  buf.set(hexToBytes(toHex), L.fields.to.offset);
  putU64Le(buf, L.fields.amount.offset, amount);
  buf.set(hexToBytes(nonceHex), L.fields.nonce.offset);
  putU64Le(buf, L.fields.expiry.offset, expiry);
  putU32Le(buf, L.fields.currency.offset, currency);
  buf.set(padName32(fromName), L.fields.from_name.offset);
  buf.set(padName32(toName), L.fields.to_name.offset);
  buf.set(padName32(memo), L.fields.memo.offset);
  return buf;
}
function buildWire(signing, sig, fromPub) {
  const wire = new Uint8Array(L.wire_len);
  wire.set(signing, L.wire_fields.signing.offset);
  wire.set(sig, L.wire_fields.sig.offset);
  wire.set(fromPub, L.wire_fields.from_pub.offset);
  return wire;
}

/**
 * Sign an authorization with `secretHex` and return the base64url wire code the relay's
 * `POST /api/v1/pay {qr}` expects (mirrors the app's signAuthorization → encodeQr pipeline). The
 * signature is byte-identical to what the on-device core / the JS shim produces (cross-validated in
 * test 00), so it settles on the real FakeLedger. `fromName` is the payer's name; `toName`/`memo`
 * are copied from the merchant's request (defaults empty — keeps the unnamed path working).
 */
export async function signAuthorizationCode(secretHex, toHex, amount, nonceHex, expiry, currency, fromName = '', toName = '', memo = '') {
  const secret = hexToBytes(secretHex);
  const pub = await ed.getPublicKeyAsync(secret);
  const fromHex = bytesToHex(pub);
  const signing = buildSigningBytes(fromHex, toHex, amount, nonceHex, expiry, currency, fromName, toName, memo);
  const sig = await ed.signAsync(signing, secret);
  return b64urlEncode(buildWire(signing, sig, pub));
}

/** CSPRNG 16-byte nonce hex (mirrors the app's randNonceHex). Uses Web Crypto (Node 18+ exposes it
 *  on globalThis.crypto), with a Math fallback that never ships to a real browser test path. */
export function randNonceHex() {
  const buf = new Uint8Array(L.nonce_len);
  if (globalThis.crypto?.getRandomValues) {
    globalThis.crypto.getRandomValues(buf);
  } else {
    for (let i = 0; i < buf.length; i++) buf[i] = Math.floor(Math.random() * 256);
  }
  return bytesToHex(buf);
}

/** Generate a fresh ed25519 keypair (a second wallet generated in-test). */
export async function generateKeypair() {
  const secret = ed.utils.randomPrivateKey();
  const pub = await ed.getPublicKeyAsync(secret);
  return { secretHex: bytesToHex(secret), publicHex: bytesToHex(pub) };
}

/**
 * Sign a WithdrawAuth and return the hex signature (mirrors dpay_core::sign_withdraw, byte-exact).
 * Used by the withdraw-errors flow to drive the relay-level enforcement gate (below-min /
 * insufficient / wrong-sig) DIRECTLY via POST /api/v1/withdraw — proving the relay rejects at the
 * API level with the right 422 + error text, complementing the app's own UI guards. The signing
 * layout is read from `wire_layout.json` (the withdraw section) so the offsets are never
 * hand-transcribed. Returns the 64-byte sig as a hex string.
 */
export async function signWithdrawalHex(secretHex, fromHex, destination, amount, nonceHex, expiry, currency) {
  const W = L.withdraw;
  const addrBytes = Uint8Array.from(Buffer.from(destination, 'utf8'));
  const buf = new Uint8Array(W.fixed_len + W.addr_len_bytes + addrBytes.length);
  let off = 0;
  buf.set(hexToBytes(fromHex), off); off += W.fields.from_pubkey.len;
  putU64Le(buf, off, amount); off += W.fields.amount.len;
  buf.set(hexToBytes(nonceHex), off); off += W.fields.nonce.len;
  putU64Le(buf, off, expiry); off += W.fields.expiry.len;
  putU32Le(buf, off, currency); off += W.fields.currency.len;
  putU32Le(buf, off, addrBytes.length); off += W.addr_len_bytes;
  buf.set(addrBytes, off);
  const sig = await ed.signAsync(buf, hexToBytes(secretHex));
  return bytesToHex(sig);
}

export const REQUEST_LEN = L.request_len;
export const SIGNING_LEN = L.signing_len;
export const WIRE_LEN = L.wire_len;
export const PUBKEY_LEN = L.pubkey_len;
export const NONCE_LEN = L.nonce_len;

// --- IC user-principal rail (2026-08-19 cutover): Node-side envelope builders ------------------
// Byte-mirrors crates/dpay-icp (envelope.rs CBOR + request_id; icrc.rs DIDL args) so harness flows
// settle on the fake-IC gateway exactly like the app does. Cross-validated against the wasm shim
// in flow 00 (cross-val) — if these drift from Rust, every pay flow goes RED loudly.

// Minimal CBOR encoder (definite-length, majors 0-5) matching dpay-icp's writer.
function cborHead(major, val) {
  const m = Number(major) << 5;
  const v = BigInt(val);
  if (v < 24n) return [m | Number(v)];
  if (v < 256n) return [m | 24, Number(v)];
  if (v < 65536n) return [m | 25, Number(v >> 8n), Number(v & 0xffn)];
  if (v < 4294967296n) return [m | 26, Number(v >> 24n), Number((v >> 16n) & 0xffn), Number((v >> 8n) & 0xffn), Number(v & 0xffn)];
  const out = [m | 27];
  for (let i = 7n; i >= 0n; i--) out.push(Number((v >> (i * 8n)) & 0xffn));
  return out;
}
function cborBytes(b) { return [...cborHead(2, b.length), ...b]; }
function cborText(t) { const u = Array.from(Buffer.from(t, 'utf8')); return [...cborHead(3, u.length), ...u]; }
function cborMap(pairs) { // pairs: [keyText, valueBytes][] — map(5-7 keys)
  const out = [...cborHead(5, pairs.length)];
  for (const [k, v] of pairs) out.push(...cborText(k), ...v);
  return out;
}

// SHA224 (principal derivation) + SHA256 (request_id) via Node crypto.
import { createHash } from 'node:crypto';
function sha224(b) { return Uint8Array.from(createHash('sha224').update(b).digest()); }
function sha256(b) { return Uint8Array.from(createHash('sha256').update(b).digest()); }

/** DER-wrap a raw ed25519 pubkey (SubjectPublicKeyInfo): 302a300506032b6570032100 || raw32. */
function derWrap(raw32) {
  return Uint8Array.from(Buffer.concat([Buffer.from('302a300506032b6570032100', 'hex'), Buffer.from(raw32)]));
}

const IC_DOMAIN = Buffer.from('\x0Aic-request', 'utf8');

// uleb128 (u128 as BigInt)
function uleb(v) {
  let x = BigInt(v); const out = [];
  do { let b = Number(x & 0x7fn); x >>= 7n; if (x > 0n) b |= 0x80; out.push(b); } while (x > 0n);
  return out;
}

/** Principal (29-byte self-authenticating) from a raw 32B ed25519 pubkey: SHA224(DER(pub)) | 0x02.
 *  `pubkey32` is the pubkey as a 64-char HEX STRING (the convention at every call site —
 *  railTransfer, railPrincipalText, the pay flows). Mirrors Rust's
 *  Principal::self_authenticating_ed25519 byte-for-byte; passing the hex through un-decoded
 *  hashes 64 ASCII chars instead of the 32 raw bytes and produces a WRONG (phantom) principal. */
export function icpPrincipalBytes(pubkey32) {
  const raw = typeof pubkey32 === 'string' ? hexToBytes(pubkey32) : pubkey32;
  const h = sha224(derWrap(raw));
  return Uint8Array.from([...h, 0x02]);
}

/** request_id (SHA256-based) over the content fields — mirrors dpay_icp::request_id.
 *  fields: {key: string, hashInput: bytes}[]; sorts by SHA256(key) (order-independent). */
/** request_id per the IC spec (mirrors dpay_icp::request_id exactly): each value is HASHED to a
 *  32-byte leaf (sha256 of str/bytes, sha256 of uleb for u64, concat of leaf hashes for arrays),
 *  pairs sort by key hash, and the result is sha256 over the concatenated (keyHash ‖ leafHash) run
 *  — NO domain prefix byte. */
function ridLeaf(v) {
  if (v.__ridArray) {
    let h = Buffer.alloc(0);
    for (const item of v.__ridArray) h = Buffer.concat([h, ridLeaf(item)]);
    return sha256(h);
  }
  return sha256(v); // values arrive pre-encoded: str/bytes raw, u64 already uleb'd
}
function requestId(fields) {
  const hashed = fields.map(([k, v]) => [sha256(Buffer.from(k, 'utf8')), ridLeaf(v)]);
  hashed.sort((a, b) => Buffer.compare(a[0], b[0]) || Buffer.compare(a[1], b[1]));
  let concat = Buffer.alloc(0);
  for (const [kh, vh] of hashed) concat = Buffer.concat([concat, kh, vh]);
  return sha256(concat);
}
function ridBytes(b) { return b; } // value = raw bytes (already hashed leaf form)
function ridU64(v) { return Uint8Array.from(uleb(BigInt(v))); } // U64 → uleb of the value

/** Sign a full /call envelope: CBOR {content:{...}, sender_pubkey: DER, sender_sig} (d9d9f7-tagged).
 *  Mirrors dpay_icp::envelope::sign_update exactly (incl. the request_id the gateway will key on).
 *  memoHex (the request nonce) is the reconciliation key inside the transfer arg. */
export async function icpSignUpdate(secretHex, canisterText, methodName, argBytes, ingressExpiryNs, opts = {}) {
  const secret = hexToBytes(secretHex);
  const pub = await ed.getPublicKeyAsync(secret);
  const der = derWrap(pub);
  const sender = Uint8Array.from([...sha224(der), 0x02]);
  const canister = canisterBytesFromText(canisterText);
  const noncePairs = opts.nonce != null ? [['nonce', cborBytes(Uint8Array.from(uleb(BigInt(opts.nonce))))]] : [];
  const contentPairs = [
    ['request_type', cborText('call')],
    ['ingress_expiry', Uint8Array.from(cborHead(0, BigInt(ingressExpiryNs)))],
    ['sender', cborBytes(sender)],
    ['canister_id', cborBytes(canister)],
    ['method_name', cborText(methodName)],
    ['arg', cborBytes(Uint8Array.from(argBytes))],
    ...noncePairs,
  ];
  const rid = requestId([
    ['request_type', ridBytes(Buffer.from('call', 'utf8'))],
    ['ingress_expiry', ridU64(ingressExpiryNs)],
    ['sender', ridBytes(sender)],
    ['canister_id', ridBytes(canister)],
    ['method_name', ridBytes(Buffer.from(methodName, 'utf8'))],
    ['arg', ridBytes(Uint8Array.from(argBytes))],
    ...(opts.nonce != null ? [['nonce', ridU64(opts.nonce)]] : []),
  ]);
  const sig = await ed.signAsync(Buffer.concat([IC_DOMAIN, rid]), secret);
  const envelope = Uint8Array.from([
    0xd9, 0xd9, 0xf7,
    ...cborMap([
      ['content', cborMap(contentPairs)],
      ['sender_pubkey', cborBytes(der)],
      ['sender_sig', cborBytes(Uint8Array.from(sig))],
    ]),
  ]);
  return { envelopeHex: bytesToHex(envelope), requestIdHex: bytesToHex(rid) };
}

// Sign a read_state envelope (paths: array of byte-arrays; e.g. [[b'request_status', rid]] and/or [[b'time']]).
// Mirrors dpay_icp::envelope::sign_read_state — content carries request_type/ingress_expiry/sender/paths (NO canister_id).
export async function icpSignReadState(secretHex, paths, ingressExpiryNs) {
  const secret = hexToBytes(secretHex);
  const pub = await ed.getPublicKeyAsync(secret);
  const der = derWrap(pub);
  const sender = Uint8Array.from([...sha224(der), 0x02]);
  // paths value: REAL CBOR array of arrays of byte strings (mirrors Rust cbor::array nesting)
  const pathArrays = paths.map((p) => [...cborHead(4, p.length), ...p.map((seg) => cborBytes(Uint8Array.from(seg))).flat()]);
  const pathsValue = [...cborHead(4, pathArrays.length), ...pathArrays.flat()];
  const contentPairs = [
    ['request_type', cborText('read_state')],
    ['ingress_expiry', cborHead(0, BigInt(ingressExpiryNs))],
    ['sender', cborBytes(sender)],
    ['paths', pathsValue],
  ];
  const rid = requestId([
    ['request_type', ridBytes(Buffer.from('read_state', 'utf8'))],
    ['ingress_expiry', ridU64(ingressExpiryNs)],
    ['sender', ridBytes(sender)],
    // paths leaf = Array of paths; each path = Array of Bytes labels (hash_leaf concatenates per-item leaves)
    ['paths', { __ridArray: paths.map((p) => ({ __ridArray: p.map((seg) => ridBytes(Buffer.from(seg))) })) }],
  ]);
  const sig = await ed.signAsync(Buffer.concat([Buffer.from(IC_DOMAIN, 'latin1'), Buffer.from(rid)]), secret);
  const envelope = Uint8Array.from([
    0xd9, 0xd9, 0xf7,
    ...cborMap([
      ['content', cborMap(contentPairs)],
      ['sender_pubkey', cborBytes(der)],
      ['sender_sig', cborBytes(Uint8Array.from(sig))],
    ]),
  ]);
  return { envelopeHex: bytesToHex(envelope), requestIdHex: bytesToHex(rid) };
}

// --- principal text codec (base32-CRC32, RFC4648 A-Z2-7 no pad) --------------------------------
const B32 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
function crc32(b) {
  let c; const table = [];
  for (let n = 0; n < 256; n++) { c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; table[n] = c >>> 0; }
  let crc = 0xffffffff;
  for (const byte of b) crc = table[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
}
/** Canonical principal TEXT: base32(CRC32-BE4(payload) || payload), RFC4648 A-Z2-7 lowercased. */
export function principalToText(bytes) {
  const payload = Buffer.from(bytes);
  const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(payload));
  const all = Buffer.concat([crc, payload]);
  let bits = 0, value = 0, out = '';
  for (const byte of all) {
    value = (value << 8) | byte; bits += 8;
    while (bits >= 5) { out += B32[(value >>> (bits - 5)) & 31]; bits -= 5; }
  }
  if (bits > 0) out += B32[(value << (5 - bits)) & 31];
  return out.toLowerCase().replace(/(.{5})/g, '$1-').replace(/-$/, '');
}
/** Raw principal bytes from canonical text (validates the CRC). */
export function principalFromText(text) {
  const clean = String(text).toLowerCase().replace(/-/g, '');
  let bits = 0, value = 0; const out = [];
  for (const ch of clean) {
    const d = B32.indexOf(ch.toUpperCase());
    if (d < 0) throw new Error('principal: bad char');
    value = (value << 5) | d; bits += 5;
    if (bits >= 8) { out.push((value >>> (bits - 8)) & 0xff); bits -= 8; }
  }
  const all = Buffer.from(out);
  if (all.length < 4) throw new Error('principal: too short');
  const payload = all.subarray(4); // CRC-first layout
  if (all.readUInt32BE(0) !== crc32(payload)) throw new Error('principal: CRC mismatch');
  return Uint8Array.from(payload);
}
function canisterBytesFromText(text) { return principalFromText(text); }

// --- DIDL codecs (byte-mirrors the golden type tables in crates/dpay-icp) ----------------------
// TRANSFER_PREFIX golden (64 bytes): DIDL + 2-record type table for icrc1_transfer_arg.
const TRANSFER_PREFIX = Buffer.from(
  '4449444c066c06fbca0101c6fcb60204ba89e5c20402a2de94eb060282f3f391' +
  '0c05d8a38ca80d7d6c02b3b0dac30368ad86ca8305026e036d7b6e7d6e780100', 'hex'
);
// sanity: 64 bytes
if (TRANSFER_PREFIX.length !== 64) throw new Error('TRANSFER_PREFIX golden length drift');

function didlPutPrincipal(bytes) { return [0x01, ...uleb(bytes.length), ...bytes]; }
function didlPutOptNat(v) { return v == null ? [0x00] : [0x01, ...uleb(BigInt(v))]; }
function didlPutOptBlob(bytes) { return bytes == null ? [0x00] : [0x01, ...uleb(bytes.length), ...bytes]; }
function didlPutOptNat64(v) {
  if (v == null) return [0x00];
  const out = [0x01]; let x = BigInt(v);
  for (let i = 0; i < 8; i++) { out.push(Number(x & 0xffn)); x >>= 8n; }
  return out;
}
function didlPutAccount(pBytes, subaccount) {
  // owner principal + subaccount opt blob (all-zero canonicalized to none)
  const sub = subaccount == null || subaccount.every(b => b === 0) ? null : subaccount;
  return [...didlPutPrincipal(pBytes), ...didlPutOptBlob(sub)];
}

/** icrc1_transfer arg (hash field order to/fee/memo/from_subaccount/created_at_time/amount),
 *  byte-mirrors dpay_icp::icrc::transfer_arg. memo = the 16B request nonce (reconciliation key). */
export function icpTransferArgBytes(toPrincipalBytes, amount, { fee = null, memoHex = '' } = {}) {
  const memo = memoHex ? hexToBytes(memoHex) : null;
  const out = [...TRANSFER_PREFIX];
  out.push(...didlPutAccount(toPrincipalBytes, null));
  out.push(...didlPutOptNat(fee));
  out.push(...didlPutOptBlob(memo));
  out.push(...didlPutOptBlob(null)); // from_subaccount (default account)
  out.push(...didlPutOptNat64(null)); // created_at_time
  out.push(...uleb(BigInt(amount)));
  return Uint8Array.from(out);
}

/** icrc1_balance_of arg (single account record), byte-mirrors ACCOUNT_PREFIX golden (25B incl trailing nargs=01 ref=00). */
const ACCOUNT_PREFIX = Buffer.from('4449444c036c02b3b0dac30368ad86ca8305016e026d7b0100', 'hex');
export function icpBalanceOfArgBytes(ownerPrincipalBytes) {
  return Uint8Array.from([...ACCOUNT_PREFIX, ...didlPutAccount(ownerPrincipalBytes, null)]);
}
